/** Minimal idb-compatible helper (promisified). */
const DBS = new Map();
function _req(r) { return new Promise((res, rej) => { r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); }); }
export async function openDB(name, ver, handlers) {
  if (DBS.has(name)) return DBS.get(name);
  const db = await new Promise((resolve, reject) => {
    const req = indexedDB.open(name, ver);
    req.onupgradeneeded = () => { if (handlers?.upgrade) handlers.upgrade(req.result); };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  DBS.set(name, db);
  return db;
}
export async function get(db, store, k) { return _req(db.transaction(store).objectStore(store).get(k)); }
export async function put(db, store, o) { return _req(db.transaction(store, 'readwrite').objectStore(store).put(o)); }
export async function del(db, store, k) { return _req(db.transaction(store, 'readwrite').objectStore(store).delete(k)); }
export async function getAll(db, store) { return _req(db.transaction(store).objectStore(store).getAll()); }
export async function clear(db, store) { return _req(db.transaction(store, 'readwrite').objectStore(store).clear()); }
